#include <cstdint>
#include <iostream>
#include <set>
#include <vector>
std::size_t cases=0;
template<bool Min>void walk(ErasablePriorityQueue<int,Min> q,std::multiset<int> expected,int depth){
 ++cases;assert(q.size()==expected.size());assert(q.empty()==expected.empty());auto copy=q;auto ref=expected;while(!ref.empty()){auto it=Min?ref.begin():std::prev(ref.end());assert(copy.extract_top()==*it);ref.erase(it);}assert(!copy.extract_top());
 if(depth==0)return;
 for(int value:{0,1,2}){auto next=q;auto r=expected;next.push(value);r.insert(value);walk(std::move(next),std::move(r),depth-1);}
 for(int value:{0,1,2})if(expected.contains(value)){auto next=q;auto r=expected;next.erase(value);r.erase(r.find(value));walk(std::move(next),std::move(r),depth-1);}
 if(!expected.empty()){auto next=q;auto r=expected;auto it=Min?r.begin():std::prev(r.end());assert(next.top()==*it);next.pop();r.erase(it);walk(std::move(next),std::move(r),depth-1);}
}
template<bool Min>void test(){for(int a=0;a<3;++a)for(int b=0;b<3;++b)for(int c=0;c<3;++c){std::vector<int>v;for(int i=0;i<a;++i)v.push_back(0);for(int i=0;i<b;++i)v.push_back(1);for(int i=0;i<c;++i)v.push_back(2);walk(ErasablePriorityQueue<int,Min>(v),std::multiset<int>(v.begin(),v.end()),5);}}
int main(){test<true>();test<false>();std::cout<<"PASS exhaustive persistent-pending states="<<cases<<'\n';}

